pragma solidity ^0.8.0;

contract ERC721Proxy {
    error ProxyDelegateCallFailed();

    address private constant ERC721_IMPL = 0xe7e4c2f766c254e427568d37e2f5b122630b8998;
    address private constant ADMIN_IMPL = 0x828eed723caf0a8f822249231266e38df614923c;

    function _getImplementation(bytes4 selector) internal pure returns (address) {
        // Admin implementation functions
        if (selector == 0x1627540c || // nominateNewOwner(address)
            selector == 0x3659cfe6 || // upgradeTo(address)
            selector == 0x53a47bb7 || // nominatedOwner()
            selector == 0x718fe928 || // renounceNomination()
            selector == 0x79ba5097 || // acceptOwnership()
            selector == 0x8da5cb5b || // owner()
            selector == 0xaaf10f42 || // getImplementation()
            selector == 0xc7f62cda) { // simulateUpgradeTo(address)
            return ADMIN_IMPL;
        }

        // ERC721 implementation functions
        if (selector == 0x01ffc9a7 || // supportsInterface(bytes4)
            selector == 0x06fdde03 || // name()
            selector == 0x081812fc || // getApproved(uint256)
            selector == 0x095ea7b3 || // approve(address,uint256)
            selector == 0x18160ddd || // totalSupply()
            selector == 0x23b872dd || // transferFrom(address,address,uint256)
            selector == 0x2f745c59 || // tokenOfOwnerByIndex(address,uint256)
            selector == 0x30176e13 || // setBaseTokenURI(string)
            selector == 0x392e53cd || // isInitialized()
            selector == 0x40c10f19 || // mint(address,uint256)
            selector == 0x42842e0e || // safeTransferFrom(address,address,uint256)
            selector == 0x42966c68 || // burn(uint256)
            selector == 0x4f6ccce7 || // tokenByIndex(uint256)
            selector == 0x6352211e || // ownerOf(uint256)
            selector == 0x70a08231 || // balanceOf(address)
            selector == 0x8832e6e3 || // safeMint(address,uint256,bytes)
            selector == 0x95d89b41 || // symbol()
            selector == 0xa22cb465 || // setApprovalForAll(address,bool)
            selector == 0xa6487c53 || // initialize(string,string,string)
            selector == 0xb88d4fde || // safeTransferFrom(address,address,uint256,bytes)
            selector == 0xc87b56dd || // tokenURI(uint256)
            selector == 0xe985e9c5 || // isApprovedForAll(address,address)
            selector == 0xff53fac7) { // setAllowance(uint256,address)
            return ERC721_IMPL;
        }

        return address(0);
    }

    fallback() external payable {
        address impl = _getImplementation(msg.sig);
        if (impl == address(0)) {
            revert ProxyDelegateCallFailed();
        }

        (bool success, bytes memory returndata) = impl.delegatecall(msg.data);
        if (success) {
            assembly {
                return(add(returndata, 0x20), mload(returndata))
            }
        } else {
            assembly {
                revert(add(returndata, 0x20), mload(returndata))
            }
        }
    }
}
