pragma solidity ^0.8.20;

contract BridgeProxy {
    bytes32 private constant IMPLEMENTATION_SLOT = 0x7050c9e0f4ca769c69bd3a8ef740bc37934f8e2c036e5a723fd8ee048ed3f8c3;
    bytes32 private constant ADMIN_SLOT = 0x10d6a54a4754c8869d6886b5f5d7fbfa5b4522237ea5c60d11bc4e7a1ff9390b;

    uint256 private _slot0;
    uint256[50] private __gap1;
    bytes32 private _tipHash;
    uint256 private _genesisBlockNumber;
    uint256 private _parentBlockInterval;
    uint256 private _lastParentBlock;
    address private _operator;

    event NewOperator(address indexed operator);
    event NewHeight(uint256 indexed height, bytes32 hash);

    function admin() external view returns (address) {
        return address(uint160(uint256(ADMIN_SLOT)));
    }

    function implementation() external view returns (address) {
        return address(uint160(uint256(IMPLEMENTATION_SLOT)));
    }

    function operator() external view returns (address) {
        return _operator;
    }

    function genesisBlockNumber() external view returns (uint256) {
        return _genesisBlockNumber;
    }

    function lastParentBlock() external view returns (uint256) {
        return _lastParentBlock;
    }

    function getParentBlockInterval() external view returns (uint256) {
        return _parentBlockInterval;
    }

    function tipHash() external view returns (bytes32) {
        return _tipHash;
    }

    function periods(bytes32 _hash) external view returns (uint32 height, uint32 parentBlockInterval_, uint32 timestamp, uint32 blockNumber) {
        bytes32 slot = keccak256(abi.encode(_hash, uint256(56)));
        uint256 data;
        assembly {
            data := sload(slot)
        }
        height = uint32(data);
        parentBlockInterval_ = uint32(data >> 32);
        timestamp = uint32(data >> 64);
        blockNumber = uint32(data >> 96);
    }

    function setOperator(address newOperator) external {
        require(msg.sender == address(uint160(uint256(ADMIN_SLOT))), "Failed to call a only-operator function from non-operator");
        _operator = newOperator;
        emit NewOperator(newOperator);
    }

    function setParentBlockInterval(uint256 interval) external {
        require(msg.sender == address(uint160(uint256(ADMIN_SLOT))), "Failed to call a only-operator function from non-operator");
        _parentBlockInterval = interval;
    }

    function initialize(uint256 genesisBlock) external {
        uint256 slot0;
        assembly {
            slot0 := sload(0)
        }
        uint8 initFlag = uint8(slot0 >> 8);
        if (initFlag == 0) {
            require(address(this).code.length > 0, "Contract instance already initialized");
        } else if (initFlag != 1) {
            revert("Contract instance already initialized");
        }

        _genesisBlockNumber = genesisBlock;
        _operator = msg.sender;

        assembly {
            sstore(0, or(and(sload(0), not(0xff00)), 0x0100))
        }
    }

    function submitPeriod(bytes32 parentId, bytes32 newId) external {
        require(msg.sender == _operator, "Failed to call a only-operator function from non-operator");

        bytes32 parentSlot = keccak256(abi.encode(parentId, uint256(56)));
        uint256 parentData;
        assembly {
            parentData := sload(parentSlot)
        }
        require(uint32(parentData >> 32) > 0, "Parent node should exist");

        bytes32 newSlot = keccak256(abi.encode(newId, uint256(56)));
        uint256 newData;
        assembly {
            newData := sload(newSlot)
        }
        require(uint32(newData >> 32) == 0, "Tried to submit the same root twice");

        uint32 parentHeight = uint32(parentData);
        uint32 newHeight = parentHeight + 1;

        if (newHeight > uint32(_lastParentBlock) + uint32(_parentBlockInterval)) {
            require(block.number >= _lastParentBlock + _parentBlockInterval, "Tried to submit new period too");
            _lastParentBlock = block.number;
        }

        uint256 packedData = uint256(newHeight) |
                            (uint256(_parentBlockInterval) << 32) |
                            (uint256(block.timestamp) << 64) |
                            (uint256(block.number) << 96);
        assembly {
            sstore(newSlot, packedData)
        }

        _tipHash = newId;

        emit NewHeight(newHeight, newId);
    }
}
