pragma solidity ^0.8.0;

interface IChainlinkAggregator {
    function latestRoundData() external view returns (
        uint80 roundId,
        int256 answer,
        uint256 startedAt,
        uint256 updatedAt,
        uint80 answeredInRound
    );
}

interface ICurvePool {
    function get_virtual_price() external view returns (uint256);
}

interface IYearnVault {
    function pricePerShare() external view returns (uint256);
}

error StalePrice();

contract PriceOracle {
    string private _name;

    function name() external view returns (string memory) {
        return _name;
    }

    function DECIMALS() external pure returns (uint8) {
        return 18;
    }

    function PRICE_MIN() external pure returns (uint256) {
        return 0;
    }

    function getPrices() external view returns (uint256, uint256, uint256) {
        IChainlinkAggregator feed1 = IChainlinkAggregator(0x8350b7de6a6a2c1368e7d4bd968190e13e354297);
        IChainlinkAggregator feed2 = IChainlinkAggregator(0xf4030086522a5beea4988f8ca5b36dbc97bee88c);
        IChainlinkAggregator feed3 = IChainlinkAggregator(0xfdfd9c85ad200c506cf9e21f1fd8dd01932fbb23);
        ICurvePool curvePool = ICurvePool(0xb7ecb2aa52aa64a717180e030241bc75cd946726);
        IYearnVault yearnVault = IYearnVault(0xb3ca5c531bcaf94c3575500da16b7e219b910224);

        (, int256 price1, , uint256 updatedAt1, ) = feed1.latestRoundData();
        if (updatedAt1 == 0) revert StalePrice();

        (, int256 price2, , uint256 updatedAt2, ) = feed2.latestRoundData();
        if (updatedAt2 == 0) revert StalePrice();

        (, int256 price3, , uint256 updatedAt3, ) = feed3.latestRoundData();
        if (updatedAt3 == 0) revert StalePrice();

        uint256 virtualPrice = curvePool.get_virtual_price();
        uint256 pps = yearnVault.pricePerShare();

        uint256 derivedPrice = (uint256(price3) * 1e8 * virtualPrice / 1e18) * pps / 1e18;

        return (uint256(price1), uint256(price2), derivedPrice);
    }
}
