// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

contract GameContract {
    address private _owner;
    uint256 private _state;
    uint256 public entryFee;
    uint256 private _characterCount;
    uint256 private _config1;
    uint256 private _config2;

    mapping(bytes32 => uint256) private _characterStorage;

    event OwnershipTransferred(address indexed previousOwner, address indexed newOwner);
    event CharacterSelect(address indexed account, uint32 characterId);

    modifier onlyOwner() {
        require(_owner == msg.sender, "Ownable: caller is not the owner");
        _;
    }

    constructor() {
        _owner = msg.sender;
        emit OwnershipTransferred(address(0), msg.sender);
    }

    function owner() external view returns (address) {
        return _owner;
    }

    function isOwner() external view returns (bool) {
        return _owner == msg.sender;
    }

    function renounceOwnership() external onlyOwner {
        emit OwnershipTransferred(_owner, address(0));
        _owner = address(0);
    }

    function transferOwnership(address newOwner) external onlyOwner {
        require(newOwner != address(0), "Ownable: new owner is the zero address");
        emit OwnershipTransferred(_owner, newOwner);
        _owner = newOwner;
    }

    function setEntryFee(uint32 fee) external onlyOwner {
        entryFee = uint256(fee);
    }

    function AddCharacter(uint32 characterId, uint256 data) external onlyOwner {
        uint256 index = _characterCount;
        _characterCount = index + 1;

        bytes32 baseSlot = keccak256(abi.encodePacked(index, uint256(3)));
        _characterStorage[baseSlot] = uint256(characterId);
        _characterStorage[bytes32(uint256(baseSlot) + 1)] = data;

        _config1 = _config1 + characterId;
        _config2 = _config2 + data;
    }

    function withdraw(address to) external onlyOwner {
        (bool success, ) = payable(to).call{value: address(this).balance}("");
        require(success, "Transfer failed");
    }

    function addrMapCharacterIds(address account) external view returns (uint32) {
        bytes32 slot = keccak256(abi.encodePacked(uint256(1), account));
        return uint32(_characterStorage[slot]);
    }

    function getConfig() external view returns (uint256[] memory) {
        uint256 count = _characterCount;
        uint256[] memory result = new uint256[](count);
        for (uint256 i = 0; i < count; i++) {
            bytes32 slot = keccak256(abi.encodePacked(i, uint256(3)));
            result[i] = _characterStorage[slot];
        }
        return result;
    }

    receive() external payable {
        require(msg.value >= entryFee, "Insufficient payment");

        uint256 random = uint256(keccak256(abi.encodePacked(
            block.timestamp,
            msg.value,
            block.prevrandao,
            _config2
        )));

        require(_characterCount > 0, "No characters");
        uint256 selectedIndex = random % _characterCount;

        bytes32 charSlot = keccak256(abi.encodePacked(selectedIndex, uint256(3)));
        uint32 characterId = uint32(_characterStorage[charSlot]);

        bytes32 addrSlot = keccak256(abi.encodePacked(uint256(1), msg.sender));
        _characterStorage[addrSlot] = uint256(characterId);

        emit CharacterSelect(msg.sender, characterId);

        uint256 refund = entryFee;
        if (msg.value > entryFee) {
            refund = msg.value - entryFee;
        }
        if (refund > 0) {
            (bool success, ) = payable(msg.sender).call{value: refund}("");
            require(success, "Transfer failed");
        }
    }
}
