// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

interface IMorpho {
    struct MarketParams {
        address loanToken;
        address collateralToken;
        address oracle;
        address irm;
        uint256 lltv;
    }

    function position(bytes32 id, address user) external view returns (uint256 collateral, uint256 shares);
    function borrow(MarketParams calldata params, uint256 amount, uint256 shares, address onBehalf, address receiver) external;
    function repay(MarketParams calldata params, uint256 amount, uint256 shares, address onBehalf, bytes calldata data) external;
    function supplyCollateral(MarketParams calldata params, uint256 amount, address onBehalf, bytes calldata data) external;
    function withdrawCollateral(MarketParams calldata params, uint256 amount, address onBehalf, address receiver) external;
}

interface IERC20 {
    function approve(address spender, uint256 amount) external returns (bool);
}

error Panic(uint256 errorCode);
error ApproveFailed();

contract MorphoWrapper {
    function redeem(address morpho, uint256 amount, bytes calldata data) external {
        (IMorpho.MarketParams memory params, address onBehalf, address receiver) = _decodeRedeemData(data);

        if (amount != type(uint256).max) {
            (uint256 collateral, ) = IMorpho(morpho).position(_marketId(params), address(this));
            if (amount > collateral) amount = collateral;
        }

        IMorpho(morpho).withdrawCollateral(params, amount, onBehalf, receiver);
    }

    function borrow(address morpho, uint256 amount, bytes calldata data) external {
        (IMorpho.MarketParams memory params, uint256 shares, address onBehalf, address receiver) = _decodeBorrowData(data);
        IMorpho(morpho).borrow(params, amount, shares, onBehalf, receiver);
    }

    function repay(address morpho, uint256 amount, bytes calldata data) external {
        (IMorpho.MarketParams memory params, uint256 shares, address onBehalf, bytes memory callbackData) = _decodeRepayData(data);
        _approve(params.loanToken, morpho, amount);
        IMorpho(morpho).repay(params, amount, shares, onBehalf, callbackData);
    }

    function mint(address morpho, uint256 amount, bytes calldata data) external {
        (IMorpho.MarketParams memory params, address onBehalf, bytes memory callbackData) = _decodeMintData(data);
        _approve(params.collateralToken, morpho, amount);
        IMorpho(morpho).supplyCollateral(params, amount, onBehalf, callbackData);
    }

    function _approve(address token, address spender, uint256 amount) internal {
        (bool success, bytes memory result) = token.call(
            abi.encodeWithSelector(IERC20.approve.selector, spender, amount)
        );
        if (!success || (result.length >= 32 && !abi.decode(result, (bool)))) {
            revert ApproveFailed();
        }
    }

    function _marketId(IMorpho.MarketParams memory params) internal pure returns (bytes32) {
        return keccak256(abi.encode(params.loanToken, params.collateralToken, params.oracle, params.irm, params.lltv));
    }

    function _decodeRedeemData(bytes calldata data) internal pure returns (IMorpho.MarketParams memory, address, address) {
        (IMorpho.MarketParams memory params, address onBehalf, address receiver) = abi.decode(data, (IMorpho.MarketParams, address, address));
        return (params, onBehalf, receiver);
    }

    function _decodeBorrowData(bytes calldata data) internal pure returns (IMorpho.MarketParams memory, uint256, address, address) {
        (IMorpho.MarketParams memory params, uint256 shares, address onBehalf, address receiver) = abi.decode(data, (IMorpho.MarketParams, uint256, address, address));
        return (params, shares, onBehalf, receiver);
    }

    function _decodeRepayData(bytes calldata data) internal pure returns (IMorpho.MarketParams memory, uint256, address, bytes memory) {
        (IMorpho.MarketParams memory params, uint256 shares, address onBehalf, bytes memory callbackData) = abi.decode(data, (IMorpho.MarketParams, uint256, address, bytes));
        return (params, shares, onBehalf, callbackData);
    }

    function _decodeMintData(bytes calldata data) internal pure returns (IMorpho.MarketParams memory, address, bytes memory) {
        (IMorpho.MarketParams memory params, address onBehalf, bytes memory callbackData) = abi.decode(data, (IMorpho.MarketParams, address, bytes));
        return (params, onBehalf, callbackData);
    }
}
