pragma solidity ^0.8.0;

interface IWETH {
    function deposit() external payable;
    function withdraw(uint256) external;
    function approve(address spender, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}

interface ISwapRouter {
    function exactInputSingle(
        address tokenIn,
        address tokenOut,
        uint24 fee,
        address recipient,
        uint256 deadline,
        uint256 amountIn,
        uint256 amountOutMinimum,
        uint160 sqrtPriceLimitX96
    ) external payable returns (uint256 amountOut);

    function exactOutputSingle(
        address tokenIn,
        address tokenOut,
        uint24 fee,
        address recipient,
        uint256 deadline,
        uint256 amountOut,
        uint256 amountInMaximum,
        uint160 sqrtPriceLimitX96
    ) external payable returns (uint256 amountIn);
}

contract UniswapV3Swap {
    string public constant name = "UniswapV3-Swap-v1";

    address private constant WETH = 0xC02aaA39b223Fe8D0A0e5C4F27eAD9083C756Cc2;
    address private constant ROUTER = 0x68b3465833fb72a70ecdf485e0e4c7bd8665fc45;
    address private constant ETH = 0xEeeeeEeeeEeEeeEeEeEeeEEEeeeeEeeeeeeeEEeE;

    function buy(
        address tokenIn,
        address tokenOut,
        uint24 fee,
        uint256 amountIn,
        uint256 minAmountOut,
        uint256 deadline,
        uint256 sqrtPriceLimitX96
    ) external payable {
        address actualTokenIn = tokenIn == ETH ? WETH : tokenIn;
        address actualTokenOut = tokenOut == ETH ? WETH : tokenOut;

        if (tokenIn == ETH) {
            IWETH(WETH).deposit{value: amountIn}();
        }

        _safeApprove(actualTokenIn, amountIn);

        ISwapRouter(ROUTER).exactOutputSingle{value: msg.value}(
            actualTokenIn,
            actualTokenOut,
            fee,
            address(this),
            deadline,
            minAmountOut,
            amountIn,
            uint160(sqrtPriceLimitX96)
        );

        if (tokenOut == ETH) {
            uint256 balance = IWETH(WETH).balanceOf(address(this));
            if (balance > 0) {
                IWETH(WETH).withdraw(balance);
            }
        }
    }

    function sell(
        address tokenIn,
        address tokenOut,
        uint24 fee,
        uint256 amountIn,
        uint256 minAmountOut,
        uint256 deadline,
        uint256 sqrtPriceLimitX96
    ) external payable {
        address actualTokenIn = tokenIn == ETH ? WETH : tokenIn;
        address actualTokenOut = tokenOut == ETH ? WETH : tokenOut;

        if (tokenIn == ETH) {
            IWETH(WETH).deposit{value: amountIn}();
        }

        _safeApprove(actualTokenIn, amountIn);

        ISwapRouter(ROUTER).exactInputSingle{value: msg.value}(
            actualTokenIn,
            actualTokenOut,
            fee,
            address(this),
            deadline,
            amountIn,
            minAmountOut,
            uint160(sqrtPriceLimitX96)
        );

        if (tokenOut == ETH) {
            uint256 balance = IWETH(WETH).balanceOf(address(this));
            if (balance > 0) {
                IWETH(WETH).withdraw(balance);
            }
        }
    }

    function _safeApprove(address token, uint256 amount) internal {
        (bool success, bytes memory data) = token.call(abi.encodeWithSelector(0x095ea7b3, ROUTER, amount));
        if (!success || (data.length > 0 && !abi.decode(data, (bool)))) {
            token.call(abi.encodeWithSelector(0x095ea7b3, ROUTER, 0));
            token.call(abi.encodeWithSelector(0x095ea7b3, ROUTER, amount));
        }
    }
}
