contract PrivateSale {
    address private _owner;
    uint256 private _maxMints;
    mapping(address => uint256) private _minted;
    bytes32 private _merkleRoot;
    uint256 private _startTime;
    uint256 private _endTime;

    event OwnershipTransferred(address indexed previousOwner, address indexed newOwner);

    error ExceedsMaxMints();
    error InvalidProof();
    error PrivateSaleNotStarted();
    error InsufficientPayment();
    error CantSendEthersToWallet();

    constructor(uint256 maxMints_) {
        _owner = msg.sender;
        _maxMints = maxMints_;
        emit OwnershipTransferred(address(0), msg.sender);
    }

    modifier onlyOwner() {
        require(_owner == msg.sender, "Ownable: caller is not the owner");
        _;
    }

    function owner() public view returns (address) {
        return _owner;
    }

    function renounceOwnership() public onlyOwner {
        _transferOwnership(address(0));
    }

    function transferOwnership(address newOwner) public onlyOwner {
        require(newOwner != address(0), "Ownable: new owner is the zero address");
        _transferOwnership(newOwner);
    }

    function _transferOwnership(address newOwner) internal {
        address oldOwner = _owner;
        _owner = newOwner;
        emit OwnershipTransferred(oldOwner, newOwner);
    }

    function isPrivateSaleStarted() public view returns (bool) {
        if (_startTime == 0) return true;
        if (_endTime == 0) return true;
        return block.timestamp >= _startTime && block.timestamp <= _endTime;
    }

    function setMerkleRoot(bytes32 merkleRoot_) public onlyOwner {
        _merkleRoot = merkleRoot_;
    }

    function changeSaleTime(uint256 startTime_, uint256 endTime_) public onlyOwner {
        _startTime = startTime_;
        _endTime = endTime_;
    }

    function getPrivateSalePrice() public pure returns (uint256) {
        return 0;
    }

    function getPrice(uint256) public pure returns (uint256) {
        return 0;
    }

    function getAvailableMints() public view returns (uint256) {
        return _maxMints - _minted[msg.sender];
    }

    function privateBuy(uint256 amount, bytes32[] calldata proof) public payable {
        if (!isPrivateSaleStarted()) revert PrivateSaleNotStarted();

        uint256 minted = _minted[msg.sender];
        if (amount > 0 && minted + amount > _maxMints) revert ExceedsMaxMints();

        bytes32 leaf = keccak256(abi.encodePacked(msg.sender, amount));
        if (!_verifyMerkleProof(proof, leaf)) revert InvalidProof();

        uint256 requiredPayment = amount * getPrivateSalePrice();
        if (msg.value < requiredPayment) revert InsufficientPayment();

        _minted[msg.sender] = minted + amount;
    }

    function _verifyMerkleProof(bytes32[] calldata proof, bytes32 leaf) internal view returns (bool) {
        bytes32 computedHash = leaf;
        for (uint256 i = 0; i < proof.length; i++) {
            bytes32 proofElement = proof[i];
            if (computedHash <= proofElement) {
                computedHash = keccak256(abi.encodePacked(computedHash, proofElement));
            } else {
                computedHash = keccak256(abi.encodePacked(proofElement, computedHash));
            }
        }
        return computedHash == _merkleRoot;
    }
}
