// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

interface IWETH {
    function deposit() external payable;
    function withdraw(uint256 amount) external;
    function transfer(address to, uint256 amount) external returns (bool);
}

interface IERC20 {
    function transfer(address to, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
}

interface IUniswapV3Pool {
    function swap(address recipient, bool zeroForOne, int256 amountSpecified, uint160 sqrtPriceLimitX96, bytes calldata data) external returns (int256 amount0, int256 amount1);
    function token0() external view returns (address);
    function token1() external view returns (address);
}

contract UniswapV3Router {
    address public immutable WETH;
    address public immutable factory;
    uint24 public immutable fee;
    bytes32 public immutable initCode;

    address public constant ETH_IDENTIFIER = 0xEeeeeEeeeEeEeeEeEeEeeEEEeeeeEeeeeeeeEEeE;

    constructor(address _weth, address _factory, uint24 _fee, bytes32 _initCode) {
        WETH = _weth;
        factory = _factory;
        fee = _fee;
        initCode = _initCode;
    }

    function buy(uint256 amountOut, uint256 amountInMax, address[] calldata path) external payable returns (uint256 amountIn) {
        require(amountOut > 1, "More than 1 token required");
        require(path.length >= 2, "Invalid path");

        uint256 pathLength = path.length;

        if (path[0] == ETH_IDENTIFIER) {
            IWETH(WETH).deposit{value: msg.value}();
        }

        amountIn = _exactOutput(amountOut, amountInMax, path);

        if (path[pathLength - 1] == ETH_IDENTIFIER) {
            IWETH(WETH).withdraw(amountIn);
            (bool success, ) = msg.sender.call{value: amountIn}("");
            require(success, "transferHelper: ETH_TRANSFER_FAILED");
        }

        require(amountIn <= amountInMax, "Excessive input amount");
    }

    function swap(uint256 amountIn, uint256 amountInMax, address[] calldata path) external payable returns (uint256 amountOut) {
        require(amountIn > 1, "More than 1 token required");
        require(path.length >= 2, "Invalid path");

        uint256 pathLength = path.length;

        if (path[0] == ETH_IDENTIFIER) {
            IWETH(WETH).deposit{value: msg.value}();
        }

        amountOut = _exactInput(amountIn, path);

        if (path[pathLength - 1] == ETH_IDENTIFIER) {
            IWETH(WETH).withdraw(amountOut);
            (bool success, ) = msg.sender.call{value: amountOut}("");
            require(success, "transferHelper: ETH_TRANSFER_FAILED");
        }
    }

    function _exactOutput(uint256 amountOut, uint256 amountInMax, address[] calldata path) internal returns (uint256 amountIn) {
        uint256 pathLength = path.length;

        for (uint256 i = pathLength - 1; i > 0; i--) {
            address tokenOut = path[i];
            address tokenIn = path[i - 1];

            bool zeroForOne = tokenIn < tokenOut;

            address pool = _getPool(tokenIn, tokenOut);

            bytes memory data = abi.encode(tokenIn, tokenOut, msg.sender);

            (int256 amount0Delta, int256 amount1Delta) = IUniswapV3Pool(pool).swap(
                address(this),
                zeroForOne,
                -int256(amountOut),
                zeroForOne ? 4295128740 : 1461446703485210103287273052203988822378259189875680,
                data
            );

            amountIn = uint256(zeroForOne ? amount0Delta : amount1Delta);
            amountOut = uint256(zeroForOne ? -amount1Delta : -amount0Delta);
        }
    }

    function _exactInput(uint256 amountIn, address[] calldata path) internal returns (uint256 amountOut) {
        uint256 pathLength = path.length;
        address tokenIn = path[0];

        for (uint256 i = 0; i < pathLength - 1; i++) {
            address tokenOut_ = path[i + 1];

            bool zeroForOne = tokenIn < tokenOut_;

            address pool = _getPool(tokenIn, tokenOut_);

            bytes memory data = abi.encode(tokenIn, tokenOut_, msg.sender);

            (int256 amount0Delta, int256 amount1Delta) = IUniswapV3Pool(pool).swap(
                i == pathLength - 2 ? msg.sender : address(this),
                zeroForOne,
                int256(amountIn),
                zeroForOne ? 4295128740 : 1461446703485210103287273052203988822378259189875680,
                data
            );

            amountOut = uint256(zeroForOne ? amount1Delta : amount0Delta);
            amountIn = amountOut;
            tokenIn = tokenOut_;
        }
    }

    function _getPool(address tokenA, address tokenB) internal view returns (address pool) {
        (address token0, address token1) = tokenA < tokenB ? (tokenA, tokenB) : (tokenB, tokenA);
        pool = address(uint160(uint256(keccak256(abi.encodePacked(
            hex'ff',
            factory,
            keccak256(abi.encodePacked(token0, token1, fee)),
            initCode
        )))));
    }

    function uniswapV3SwapCallback(int256 amount0Delta, int256 amount1Delta, bytes calldata data) external {
        require(amount0Delta > 0 || amount1Delta > 0, "Invalid delta");

        (address tokenIn, address tokenOut, address payer) = abi.decode(data, (address, address, address));

        uint256 amountToPay = uint256(amount0Delta > 0 ? amount0Delta : amount1Delta);

        if (tokenIn == ETH_IDENTIFIER) {
            IWETH(WETH).withdraw(amountToPay);
            (bool success, ) = msg.sender.call{value: amountToPay}("");
            require(success, "transferHelper: ETH_TRANSFER_FAILED");
        } else {
            IERC20(tokenIn).transferFrom(payer, msg.sender, amountToPay);
        }
    }
}
