contract TokenVesting {
    error InvalidAddress();
    error InvalidAmount();
    error InsufficientBalance();
    error TransferFailed();
    error AddVestingFailed();
    error NotInitialized();
    error Unauthorized();
    error WithdrawFailed();
    error ArrayLengthMismatch();

    event OwnershipTransferred(address indexed previousOwner, address indexed newOwner);
    event OwnershipTransferStarted(address indexed owner, address indexed pendingOwner);
    event TokensVested(address indexed beneficiary, uint256 totalAmount, uint256[] amounts, uint256[] timestamps, uint256[] releasePercents);
    event TokensWithdrawn(address indexed to, uint256 amount);

    address private immutable TOKEN;
    address private vestingContract;
    address private owner;
    address private pendingOwner;
    bool private initialized;

    constructor(address _token) {
        TOKEN = _token;
        owner = msg.sender;
        emit OwnershipTransferred(address(0), msg.sender);
    }

    modifier onlyOwner() {
        if (msg.sender != owner) revert Unauthorized();
        _;
    }

    modifier onlyVestingContract() {
        if (msg.sender != vestingContract) revert Unauthorized();
        _;
    }

    modifier whenInitialized() {
        if (!initialized) revert NotInitialized();
        _;
    }

    function token() external view returns (address) {
        return TOKEN;
    }

    function vestingContract() external view returns (address) {
        return vestingContract;
    }

    function owner() external view returns (address) {
        return owner;
    }

    function pendingOwner() external view returns (address) {
        return pendingOwner;
    }

    function renounceOwnership() external onlyOwner {
        _transferOwnership(address(0));
    }

    function acceptOwnership() external {
        if (msg.sender != pendingOwner) revert Unauthorized();
        _transferOwnership(pendingOwner);
    }

    function transferOwnership(address newOwner) external onlyOwner {
        pendingOwner = newOwner;
        emit OwnershipTransferStarted(owner, newOwner);
    }

    function _transferOwnership(address newOwner) private {
        address oldOwner = owner;
        owner = newOwner;
        pendingOwner = address(0);
        emit OwnershipTransferred(oldOwner, newOwner);
    }

    function initialize(address _vestingContract) external onlyOwner {
        require(!initialized, "Already initialized");
        vestingContract = _vestingContract;
        initialized = true;
    }

    function vestTokens(address beneficiary, uint256 amount) external onlyVestingContract whenInitialized {
        if (beneficiary == address(0)) revert InvalidAddress();
        if (amount == 0) revert InvalidAmount();

        IERC20 tokenContract = IERC20(TOKEN);
        uint256 balance = tokenContract.balanceOf(address(this));
        if (balance < amount) revert InsufficientBalance();

        (bool success, ) = TOKEN.call(abi.encodeWithSelector(IERC20.transfer.selector, beneficiary, amount));
        if (!success) revert TransferFailed();

        emit TokensVested(beneficiary, amount, new uint256[](0), new uint256[](0), new uint256[](0));
    }

    function addVesting(
        address beneficiary,
        uint256 totalAmount,
        uint256[] calldata amounts,
        uint256[] calldata timestamps,
        uint256[] calldata releasePercents
    ) external onlyVestingContract whenInitialized {
        if (beneficiary == address(0)) revert InvalidAddress();
        if (amounts.length != timestamps.length) revert ArrayLengthMismatch();
        if (amounts.length != releasePercents.length) revert ArrayLengthMismatch();

        IERC20 tokenContract = IERC20(TOKEN);
        uint256 balance = tokenContract.balanceOf(address(this));
        if (balance < totalAmount) revert InsufficientBalance();

        (bool success, ) = TOKEN.call(abi.encodeWithSelector(IERC20.transfer.selector, beneficiary, totalAmount));
        if (!success) revert TransferFailed();

        emit TokensVested(beneficiary, totalAmount, amounts, timestamps, releasePercents);
    }

    function withdrawTokens() external onlyOwner whenInitialized {
        IERC20 tokenContract = IERC20(TOKEN);
        uint256 balance = tokenContract.balanceOf(address(this));
        if (balance == 0) revert InsufficientBalance();

        (bool success, ) = TOKEN.call(abi.encodeWithSelector(IERC20.transfer.selector, owner, balance));
        if (!success) revert WithdrawFailed();

        emit TokensWithdrawn(owner, balance);
    }
}
