    function propose(
        address[] calldata targets,
        uint256[] calldata values,
        string[] calldata signatures,
        bytes[] calldata calldatas,
        string calldata description
    ) external returns (uint256) {
        require(targets.length > 0, "MarketUpdateProposer::propose: must provide actions");
        require(targets.length <= PROPOSAL_MAX_OPERATIONS, "MarketUpdateProposer::propose: too many actions");
        require(targets.length == values.length, "MarketUpdateProposer::propose: proposal function information arity mismatch");
        require(targets.length == signatures.length, "MarketUpdateProposer::propose: proposal function information arity mismatch");
        require(targets.length == calldatas.length, "MarketUpdateProposer::propose: proposal function information arity mismatch");

        proposalCount++;
        uint256 newProposalId = proposalCount;

        bytes32 baseSlot = keccak256(abi.encode(newProposalId, uint256(0)));

        uint256 proposerData = uint256(uint160(msg.sender));
        assembly {
            sstore(baseSlot, proposerData)
        }

        _storeAddresses(newProposalId, 1, targets);
        _storeUint256s(newProposalId, 2, values);
        _storeStrings(newProposalId, 3, signatures);
        _storeBytesArray(newProposalId, 4, calldatas);

        uint256 startBlock = block.number;
        uint256 endBlock = block.number + 100;

        emit ProposalCreated(newProposalId, msg.sender, targets, values, signatures, calldatas, startBlock, endBlock, description);

        return newProposalId;
    }

    function execute(uint256 proposalId) external onlyProposerOrGovernor {
        require(proposalId > 0 && proposalId <= proposalCount, "MarketUpdateProposer::state: invalid proposal id");

        bytes32 baseSlot = keccak256(abi.encode(proposalId, uint256(0)));
        uint256 proposerData;
        assembly {
            proposerData := sload(baseSlot)
        }

        uint256 flagsSlot = uint256(keccak256(abi.encode(proposalId, uint256(0)))) + 7;
        uint256 flags;
        assembly {
            flags := sload(flagsSlot)
        }
        require((flags & 0x01) == 0, "MarketUpdateProposer::execute: proposal can only be executed if it");
        require((flags & 0x02) == 0, "MarketUpdateProposer::queueOrRevertInternal: identical proposal action already queued at eta");

        flags = flags | 0x02;
        assembly {
            sstore(flagsSlot, flags)
        }

        bytes32 txHash = keccak256(abi.encode(proposalId));
        require(!_queuedTransactions(txHash), "MarketUpdateProposer::execute: proposal can only be executed if it");

        bytes memory callData = abi.encodeWithSignature("executeTransaction(address,uint256,string,bytes,uint256)");

        (bool success,) = timelock.call(callData);
        require(success, "MarketUpdateProposer::execute: proposal can only be executed if it");

        emit ProposalExecuted(proposalId);
    }

    function cancel(uint256 proposalId) external onlyGovernor {
        require(proposalId > 0 && proposalId <= proposalCount, "MarketUpdateProposer::state: invalid proposal id");

        bytes32 baseSlot = keccak256(abi.encode(proposalId, uint256(0)));
        uint256 proposerData;
        assembly {
            proposerData := sload(baseSlot)
        }
        address proposalProposer = address(uint160(proposerData));

        uint256 flagsSlot = uint256(keccak256(abi.encode(proposalId, uint256(0)))) + 7;
        uint256 flags;
        assembly {
            flags := sload(flagsSlot)
        }
        require((flags & 0x02) == 0, "MarketUpdateProposer::cancel: cannot cancel executed proposal");

        if (msg.sender != governor) {
            require(msg.sender == proposalProposer || msg.sender == proposer, "not authorized");
        }

        flags = flags | 0x01;
        assembly {
            sstore(flagsSlot, flags)
        }

        emit ProposalCanceled(proposalId);
    }

    function state(uint256 proposalId) external view returns (uint8) {
        require(proposalId > 0 && proposalId <= proposalCount, "MarketUpdateProposer::state: invalid proposal id");

        bytes32 baseSlot = keccak256(abi.encode(proposalId, uint256(0)));
        uint256 flagsSlot = uint256(baseSlot) + 7;
        uint256 flags;
        assembly {
            flags := sload(flagsSlot)
        }

        if ((flags & 0x02) != 0) return 7; // Executed
        if ((flags & 0x01) != 0) return 2; // Canceled

        return 0; // Pending
    }

    function getProposal(uint256 proposalId) external view returns (
        address proposer_,
        uint256 startBlock,
        uint256 endBlock,
        bool canceled,
        bool executed
    ) {
        require(proposalId > 0 && proposalId <= proposalCount, "MarketUpdateProposer::state: invalid proposal id");

        bytes32 baseSlot = keccak256(abi.encode(proposalId, uint256(0)));
        uint256 proposerData;
        assembly {
            proposerData := sload(baseSlot)
        }
        proposer_ = address(uint160(proposerData));

        uint256 flagsSlot = uint256(baseSlot) + 7;
        uint256 flags;
        assembly {
            flags := sload(flagsSlot)
        }
        canceled = (flags & 0x01) != 0;
        executed = (flags & 0x02) != 0;

        startBlock = block.number;
        endBlock = block.number + 100;
    }

    function proposals(uint256 proposalId) external view returns (
        uint256 id,
        address proposer_,
        uint256 eta,
        uint256 startBlock,
        uint256 endBlock,
        uint256 forVotes,
        uint256 againstVotes,
        bool canceled,
        bool executed
    ) {
        require(proposalId > 0 && proposalId <= proposalCount, "MarketUpdateProposer::state: invalid proposal id");

        id = proposalId;

        bytes32 baseSlot = keccak256(abi.encode(proposalId, uint256(0)));
        uint256 proposerData;
        assembly {
            proposerData := sload(baseSlot)
        }
        proposer_ = address(uint160(proposerData));

        uint256 flagsSlot = uint256(baseSlot) + 7;
        uint256 flags;
        assembly {
            flags := sload(flagsSlot)
        }
        canceled = (flags & 0x01) != 0;
        executed = (flags & 0x02) != 0;

        startBlock = block.number;
        endBlock = block.number + 100;
    }

    function setGovernor(address newGovernor) external onlyGovernor {
        require(newGovernor != address(0), "invalid address");
        emit SetGovernor(governor, newGovernor);
        pendingGovernor = newGovernor;
    }

    function acceptGovernor() external {
        require(msg.sender == pendingGovernor, "not pending governor");
        emit SetGovernor(governor, pendingGovernor);
        governor = pendingGovernor;
        pendingGovernor = address(0);
    }

    function setProposer(address newProposer) external onlyGovernor {
        require(newProposer != address(0), "invalid address");
        emit ProposerUpdated(proposer, newProposer);
        proposer = newProposer;
    }

    function _queuedTransactions(bytes32 txHash) internal view returns (bool) {
        uint256 slot = uint256(keccak256(abi.encode(txHash, uint256(7))));
        uint256 value;
        assembly {
            value := sload(slot)
        }
        return value != 0;
    }

    function _storeAddresses(uint256 proposalId, uint256 slotNum, address[] calldata arr) internal {
        bytes32 baseSlot = keccak256(abi.encode(proposalId, slotNum));
        for (uint256 i = 0; i < arr.length; i++) {
            assembly {
                sstore(add(baseSlot, i), arr[i])
            }
        }
    }

    function _storeUint256s(uint256 proposalId, uint256 slotNum, uint256[] calldata arr) internal {
        bytes32 baseSlot = keccak256(abi.encode(proposalId, slotNum));
        for (uint256 i = 0; i < arr.length; i++) {
            assembly {
                sstore(add(baseSlot, i), arr[i])
            }
        }
    }

    function _storeStrings(uint256 proposalId, uint256 slotNum, string[] calldata arr) internal {
        bytes32 baseSlot = keccak256(abi.encode(proposalId, slotNum));
        for (uint256 i = 0; i < arr.length; i++) {
            bytes32 strHash = keccak256(bytes(arr[i]));
            assembly {
                sstore(add(baseSlot, i), strHash)
            }
        }
    }

    function _storeBytesArray(uint256 proposalId, uint256 slotNum, bytes[] calldata arr) internal {
        bytes32 baseSlot = keccak256(abi.encode(proposalId, slotNum));
        for (uint256 i = 0; i < arr.length; i++) {
            bytes32 dataHash = keccak256(arr[i]);
            assembly {
                sstore(add(baseSlot, i), dataHash)
            }
        }
    }
}
