pragma solidity ^0.4.24;

contract Token {
    event Transfer(address indexed from, address indexed to, uint256 value);
    event Approval(address indexed owner, address indexed spender, uint256 value);
    event OwnershipTransferred(address indexed previousOwner, address indexed newOwner);
    event OwnershipRenounced(address indexed previousOwner);
    event Mint(address indexed to, uint256 amount);
    event Burn(address indexed burner, uint256 value);
    event MintFinished();
    event Pause();
    event Unpause();
    event MinterTransferred(address indexed previousMinter, address indexed newMinter);
    event AssignerTransferred(address indexed previousAssigner, address indexed newAssigner);
    event BurnerTransferred(address indexed previousBurner, address indexed newBurner);
    event Assign(address indexed to, uint256 amount);
    event BatchMint(uint256 count, uint256 totalAmount);
    event BatchAssign(uint256 count, uint256 totalAmount);
    event BatchTransfer(uint256 count, uint256 totalAmount);

    mapping(address => uint256) public balanceOf;
    uint256 public totalSupply;
    mapping(address => mapping(address => uint256)) public allowance;
    address public owner;
    bool public mintingFinished;
    uint256 public cap;
    string public name;
    string public symbol;
    uint8 public decimals;
    bool public paused;
    address public minter;
    address public assigner;
    address public burner;

    modifier onlyOwner() {
        require(msg.sender == owner);
        _;
    }

    modifier whenNotPaused() {
        require(!paused);
        _;
    }

    modifier whenPaused() {
        require(paused);
        _;
    }

    modifier onlyMinter() {
        require(msg.sender == minter);
        _;
    }

    modifier onlyAssigner() {
        require(msg.sender == assigner);
        _;
    }

    modifier onlyBurner() {
        require(msg.sender == burner);
        _;
    }

    modifier canMint() {
        require(!mintingFinished);
        _;
    }

    constructor(string _name, string _symbol, uint8 _decimals, uint256 _cap) public {
        owner = msg.sender;
        name = _name;
        symbol = _symbol;
        decimals = _decimals;
        cap = _cap;
        minter = msg.sender;
        assigner = msg.sender;
        burner = msg.sender;
    }

    function transfer(address _to, uint256 _value) public whenNotPaused returns (bool) {
        require(mintingFinished);
        require(_to != address(0));
        require(_value <= balanceOf[msg.sender]);
        require(_value > 0);

        balanceOf[msg.sender] -= _value;
        balanceOf[_to] += _value;
        emit Transfer(msg.sender, _to, _value);
        return true;
    }

    function approve(address _spender, uint256 _value) public returns (bool) {
        allowance[msg.sender][_spender] = _value;
        emit Approval(msg.sender, _spender, _value);
        return true;
    }

    function transferFrom(address _from, address _to, uint256 _value) public whenNotPaused returns (bool) {
        require(_to != address(0));
        require(_value <= balanceOf[_from]);
        require(_value <= allowance[_from][msg.sender]);

        balanceOf[_from] -= _value;
        balanceOf[_to] += _value;
        allowance[_from][msg.sender] -= _value;
        emit Transfer(_from, _to, _value);
        return true;
    }

    function increaseApproval(address _spender, uint256 _addedValue) public returns (bool) {
        allowance[msg.sender][_spender] += _addedValue;
        emit Approval(msg.sender, _spender, allowance[msg.sender][_spender]);
        return true;
    }

    function decreaseApproval(address _spender, uint256 _subtractedValue) public returns (bool) {
        uint256 oldValue = allowance[msg.sender][_spender];
        if (_subtractedValue >= oldValue) {
            allowance[msg.sender][_spender] = 0;
        } else {
            allowance[msg.sender][_spender] = oldValue - _subtractedValue;
        }
        emit Approval(msg.sender, _spender, allowance[msg.sender][_spender]);
        return true;
    }

    function mint(address _to, uint256 _amount) public onlyMinter canMint returns (bool) {
        require(!mintingFinished);
        require(_to != address(0));
        require(totalSupply + _amount >= totalSupply);
        require(totalSupply + _amount <= cap);

        totalSupply += _amount;
        balanceOf[_to] += _amount;
        emit Mint(_to, _amount);
        emit Transfer(address(0), _to, _amount);
        return true;
    }

    function finishMinting() public onlyOwner canMint returns (bool) {
        mintingFinished = true;
        emit MintFinished();
        return true;
    }

    function setMinter(address _newMinter) public onlyOwner {
        require(!mintingFinished);
        require(_newMinter != address(0));
        require(_newMinter != minter);

        emit MinterTransferred(minter, _newMinter);
        minter = _newMinter;
    }

    function burn(uint256 _amount) public onlyBurner {
        require(_amount > 0);
        require(_amount <= balanceOf[msg.sender]);

        balanceOf[msg.sender] -= _amount;
        totalSupply -= _amount;
        emit Burn(msg.sender, _amount);
        emit Transfer(msg.sender, address(0), _amount);
    }

    function setBurner(address _newBurner) public onlyOwner {
        require(_newBurner != address(0));
        require(_newBurner != burner);

        emit BurnerTransferred(burner, _newBurner);
        burner = _newBurner;
    }

    function assign(address _to, uint256 _amount) public onlyAssigner returns (bool) {
        require(!mintingFinished);
        require(_to != address(0));
        require(_amount > 0);
        require(totalSupply + _amount >= totalSupply);
        require(totalSupply + _amount <= cap);

        totalSupply += _amount;
        balanceOf[_to] += _amount;
        emit Assign(_to, _amount);
        emit Transfer(address(0), _to, _amount);
        return true;
    }

    function setAssigner(address _newAssigner) public onlyOwner {
        require(_newAssigner != address(0));
        require(_newAssigner != assigner);

        emit AssignerTransferred(assigner, _newAssigner);
        assigner = _newAssigner;
    }

    function pause() public onlyOwner whenNotPaused {
        paused = true;
        emit Pause();
    }

    function unpause() public onlyOwner whenPaused {
        paused = false;
        emit Unpause();
    }

    function batchMint(address[] _recipients, uint256[] _amounts, uint256 _totalAmount) public onlyMinter canMint returns (bool) {
        require(_recipients.length == _amounts.length);
        require(totalSupply + _totalAmount >= totalSupply);
        require(totalSupply + _totalAmount <= cap);

        for (uint256 i = 0; i < _recipients.length; i++) {
            require(_recipients[i] != address(0));
            totalSupply += _amounts[i];
            balanceOf[_recipients[i]] += _amounts[i];
            emit Mint(_recipients[i], _amounts[i]);
            emit Transfer(address(0), _recipients[i], _amounts[i]);
        }

        emit BatchMint(_recipients.length, _totalAmount);
        return true;
    }

    function batchAssign(address[] _recipients, uint256[] _amounts, uint256 _totalAmount) public onlyAssigner returns (bool) {
        require(!mintingFinished);
        require(_recipients.length == _amounts.length);
        require(totalSupply + _totalAmount >= totalSupply);
        require(totalSupply + _totalAmount <= cap);

        for (uint256 i = 0; i < _recipients.length; i++) {
            require(_recipients[i] != address(0));
            totalSupply += _amounts[i];
            balanceOf[_recipients[i]] += _amounts[i];
            emit Assign(_recipients[i], _amounts[i]);
            emit Transfer(address(0), _recipients[i], _amounts[i]);
        }

        emit BatchAssign(_recipients.length, _totalAmount);
        return true;
    }

    function transferInBatches(address[] _recipients, uint256[] _amounts, uint256 _totalAmount) public whenNotPaused returns (bool) {
        require(mintingFinished);
        require(_recipients.length == _amounts.length);
        require(balanceOf[msg.sender] >= _totalAmount);

        for (uint256 i = 0; i < _recipients.length; i++) {
            require(_recipients[i] != address(0));
            require(_amounts[i] > 0);
            balanceOf[msg.sender] -= _amounts[i];
            balanceOf[_recipients[i]] += _amounts[i];
            emit Transfer(msg.sender, _recipients[i], _amounts[i]);
        }

        emit BatchTransfer(_recipients.length, _totalAmount);
        return true;
    }

    function transferOwnership(address _newOwner) public onlyOwner {
        require(_newOwner != address(0));
        require(_newOwner != owner);

        emit OwnershipTransferred(owner, _newOwner);
        owner = _newOwner;
    }

    function renounceOwnership() public onlyOwner {
        emit OwnershipRenounced(owner);
        emit OwnershipTransferred(owner, address(0));
        owner = address(0);
    }
}
