        assembly { sstore(OWNER_SLOT, and(initialOwner, 0xffffffffffffffffffffffffffffffffffffffff)) }
        assembly { sstore(INITIALIZED_SLOT, or(sload(INITIALIZED_SLOT), 1)) }

