pragma solidity ^0.8.0;

interface IERC721Receiver {
    function onERC721Received(address operator, address from, uint256 tokenId, bytes calldata data) external returns (bytes4);
}

contract WikiNFT {
    event Transfer(address indexed from, address indexed to, uint256 indexed tokenId);
    event Approval(address indexed owner, address indexed approved, uint256 indexed tokenId);
    event ApprovalForAll(address indexed owner, address indexed operator, bool approved);
    event OwnershipTransferred(address indexed previousOwner, address indexed newOwner);
    event WikiPageChanged(uint256 indexed tokenId);

    address private _owner;
    mapping(uint256 => address) private _tokenOwner;
    mapping(uint256 => address) private _tokenApprovals;
    mapping(address => uint256) private _balances;
    mapping(address => mapping(address => bool)) private _operatorApprovals;

    struct WikiPage {
        string title;
        string articleHash;
        string imageHash;
        uint256 price;
    }

    WikiPage[] private _wikiPages;
    mapping(address => uint256) private _ownedTokensCount;
    mapping(uint256 => uint256) private _ownedTokensIndex;
    uint256 private _costToCreate;
    mapping(uint256 => mapping(address => bool)) private _collaborators;

    string private _name = "WikiNFT";
    string private _symbol = "WIKI";

    modifier onlyOwner() {
        require(msg.sender == _owner, "Not owner");
        _;
    }

    constructor() {
        _owner = msg.sender;
        emit OwnershipTransferred(address(0), msg.sender);
    }

    function name() public view returns (string memory) {
        return _name;
    }

    function symbol() public view returns (string memory) {
        return _symbol;
    }

    function owner() public view returns (address) {
        return _owner;
    }

    function balanceOf(address owner_) public view returns (uint256) {
        require(owner_ != address(0), "Zero address");
        return _balances[owner_];
    }

    function ownerOf(uint256 tokenId) public view returns (address) {
        address owner_ = _tokenOwner[tokenId];
        require(owner_ != address(0), "Invalid token");
        return owner_;
    }

    function getApproved(uint256 tokenId) public view returns (address) {
        return _tokenApprovals[tokenId];
    }

    function isApprovedForAll(address owner_, address operator) public view returns (bool) {
        return _operatorApprovals[owner_][operator];
    }

    function approve(address to, uint256 tokenId) public {
        address owner_ = ownerOf(tokenId);
        require(to != owner_, "Approval to current owner");
        require(msg.sender == owner_ || isApprovedForAll(owner_, msg.sender), "Not approved");
        _tokenApprovals[tokenId] = to;
        emit Approval(owner_, to, tokenId);
    }

    function setApprovalForAll(address operator, bool approved) public {
        require(operator != msg.sender, "Approve to caller");
        _operatorApprovals[msg.sender][operator] = approved;
        emit ApprovalForAll(msg.sender, operator, approved);
    }

    function transferFrom(address from, address to, uint256 tokenId) public {
        require(_isApprovedOrOwner(msg.sender, tokenId), "Not approved");
        _transfer(from, to, tokenId);
    }

    function safeTransferFrom(address from, address to, uint256 tokenId) public {
        safeTransferFrom(from, to, tokenId, "");
    }

    function safeTransferFrom(address from, address to, uint256 tokenId, bytes memory data) public {
        transferFrom(from, to, tokenId);
        require(_checkOnERC721Received(from, to, tokenId, data), "Transfer to non ERC721Receiver");
    }

    function _isApprovedOrOwner(address spender, uint256 tokenId) internal view returns (bool) {
        address owner_ = _tokenOwner[tokenId];
        return (spender == owner_ || _tokenApprovals[tokenId] == spender || _operatorApprovals[owner_][spender]);
    }

    function _transfer(address from, address to, uint256 tokenId) internal {
        require(_tokenOwner[tokenId] == from, "Incorrect owner");
        require(to != address(0), "Zero address");

        _tokenApprovals[tokenId] = address(0);
        emit Approval(from, address(0), tokenId);

        _balances[from] -= 1;
        _balances[to] += 1;
        _tokenOwner[tokenId] = to;

        emit Transfer(from, to, tokenId);
    }

    function _mint(address to, uint256 tokenId) internal {
        require(to != address(0), "Zero address");
        require(_tokenOwner[tokenId] == address(0), "Already exists");

        _balances[to] += 1;
        _tokenOwner[tokenId] = to;

        emit Transfer(address(0), to, tokenId);
    }

    function _checkOnERC721Received(address from, address to, uint256 tokenId, bytes memory data) internal returns (bool) {
        if (to.code.length > 0) {
            try IERC721Receiver(to).onERC721Received(msg.sender, from, tokenId, data) returns (bytes4 retval) {
                return retval == IERC721Receiver.onERC721Received.selector;
            } catch {
                return false;
            }
        }
        return true;
    }

    function createWikiPage(string memory title, string memory articleHash, string memory imageHash, uint256 price) public onlyOwner {
        uint256 tokenId = _wikiPages.length;
        _wikiPages.push(WikiPage(title, articleHash, imageHash, price));
        _mint(msg.sender, tokenId);
    }

    function paidCreateWikiPage(string memory title, string memory articleHash, string memory imageHash, uint256 price) public payable {
        require(msg.value >= _costToCreate, "Insufficient payment");
        uint256 tokenId = _wikiPages.length;
        _wikiPages.push(WikiPage(title, articleHash, imageHash, price));
        _mint(msg.sender, tokenId);
    }

    function wikiPages(uint256 index) public view returns (string memory, string memory, string memory, uint256) {
        require(index < _wikiPages.length, "Invalid index");
        WikiPage memory page = _wikiPages[index];
        return (page.title, page.articleHash, page.imageHash, page.price);
    }

    function numberWikiPages() public view returns (uint256) {
        return _wikiPages.length;
    }

    function setCostToCreate(uint256 cost) public onlyOwner {
        _costToCreate = cost;
    }

    function setImageHash(uint256 tokenId, string memory imageHash) public {
        require(_isApprovedOrOwner(msg.sender, tokenId) || _collaborators[tokenId][msg.sender], "Not authorized");
        _wikiPages[tokenId].imageHash = imageHash;
        emit WikiPageChanged(tokenId);
    }

    function setArticleHash(uint256 tokenId, string memory articleHash) public {
        require(_isApprovedOrOwner(msg.sender, tokenId) || _collaborators[tokenId][msg.sender], "Not authorized");
        _wikiPages[tokenId].articleHash = articleHash;
        emit WikiPageChanged(tokenId);
    }

    function addCollaborator(uint256 tokenId, address collaborator) public {
        require(_isApprovedOrOwner(msg.sender, tokenId), "Not authorized");
        _collaborators[tokenId][collaborator] = true;
    }

    function removeCollaborator(uint256 tokenId, address collaborator) public {
        require(_isApprovedOrOwner(msg.sender, tokenId), "Not authorized");
        _collaborators[tokenId][collaborator] = false;
    }

    function collaborators(uint256 tokenId, address collaborator) public view returns (bool) {
        return _collaborators[tokenId][collaborator];
    }

    function buyFromCurrentOwner(uint256 tokenId) public payable {
        address owner_ = _tokenOwner[tokenId];
        require(msg.sender != owner_, "Buy from self");
        require(msg.value >= _wikiPages[tokenId].price, "Insufficient payment");

        (bool success, ) = payable(owner_).call{value: msg.value}("");
        require(success, "Transfer failed");

        _transfer(owner_, msg.sender, tokenId);
    }

    function sendBalance() public onlyOwner {
        payable(_owner).transfer(address(this).balance);
    }

    function transferOwnership(address newOwner) public onlyOwner {
        require(newOwner != address(0), "Zero address");
        address oldOwner = _owner;
        _owner = newOwner;
        emit OwnershipTransferred(oldOwner, newOwner);
    }

    function getContractBalance() public view returns (uint256) {
        return address(this).balance;
    }

    function exists(uint256 tokenId) public view returns (bool) {
        return _tokenOwner[tokenId] != address(0);
    }

    function tokenOfOwnerByIndex(address owner_, uint256 index) public view returns (uint256) {
        require(index < _balances[owner_], "Index out of bounds");
        uint256 count = 0;
        for (uint256 i = 0; i < _wikiPages.length; i++) {
            if (_tokenOwner[i] == owner_) {
                if (count == index) return i;
                count++;
            }
        }
        revert("Not found");
    }
}
