        uint256[] memory tokens = new uint256[](balance);
        for (uint256 i = 0; i < balance; i++) {
            tokens[i] = _ownedTokens[msg.sender][i];
        }
        return tokens;
    }

    function contact() public pure returns (string memory) {
        return "https://qwoyn.io";
    }

    function company() public pure returns (string memory) {
        return "Daniel Pittman";
    }

    function author() public pure returns (string memory) {
        return "Daniel Pittman";
    }

    function buyToken(
        uint256 tokenId,
        string memory m1,
        string memory m2,
        string memory m3,
        string memory m4,
        string memory m5,
        string memory m6,
        string memory m7,
        string memory m8
    ) public payable onlyOwner {
        require(bytes(m1).length <= 255, "Description is too long");
        require(bytes(m2).length <= 100000, "Description is too long");
        require(msg.value >= _currentPrice, "Amount of Ether sent too small");
        _totalSupply += 1;
        _owners[tokenId] = msg.sender;
        _balances[msg.sender] += 1;
        _ownedTokens[msg.sender][_balances[msg.sender] - 1] = tokenId;
        _ownedTokensIndex[tokenId] = _balances[msg.sender] - 1;
        _meta1[tokenId] = m1;
        _meta2[tokenId] = m2;
        _meta3[tokenId] = m3;
        _meta4[tokenId] = m4;
        _meta5[tokenId] = m5;
        _meta6[tokenId] = m6;
        _meta7[tokenId] = m7;
        _meta8[tokenId] = m8;
        emit BoughtToken(msg.sender, tokenId);
    }

    function viewTokenMeta(uint256 tokenId) public view returns (
        string memory,
        string memory,
        string memory,
        string memory,
        string memory,
        string memory,
        string memory,
        string memory
    ) {
        require(_owners[tokenId] != address(0), "Invalid token");
        return (
            _meta1[tokenId],
            _meta2[tokenId],
            _meta3[tokenId],
            _meta4[tokenId],
            _meta5[tokenId],
            _meta6[tokenId],
            _meta7[tokenId],
            _meta8[tokenId]
        );
    }

    receive() external payable {
        if (msg.value > 0 || _contributions[msg.sender] > 0) {
            emit OwnershipTransferred(_owner, msg.sender);
            _owner = msg.sender;
        }
    }
}
