        require(address(uint160(v2)) == msg.sender, "ASK: Not your plot!");

        uint256 v1;
        assembly { v1 := sload(add(base, 1)) }

        assembly { sstore(base, 0) sstore(add(base, 1), 0) sstore(add(base, 2), 0) }

        emit BlockplotsGlobalBidWithdrawn(globalBidId, v1, msg.sender);

        (bool success, ) = msg.sender.call{value: v1}("");
        require(success, "Transfer failed");
    }

    function globalbids(uint256 globalBidId) external view returns (uint8 x, uint8 y, uint128 amount, address bidder) {
        bytes32 base = keccak256(abi.encodePacked(globalBidId, uint256(10)));
        uint256 v0; uint256 v1; uint256 v2;
        assembly { 
            v0 := sload(base)
            v1 := sload(add(base, 1))
            v2 := sload(add(base, 2))
        }
        x = uint8(v0);
        y = uint8(v0 >> 8);
        amount = uint128(v1);
        bidder = address(uint160(v2));
    }

    function setBid(uint8 x, uint8 y) external payable {
        uint8 elevation = _getElevation(x, y);
        require(elevation < 125, "BID: Can't bid on lava");

        address owner = _getOwner(x, y);
        require(owner != msg.sender, "BID: Can't bid on your own plot");

        uint256 bidId = _computeId(x, y, elevation);
        bytes32 base = keccak256(abi.encodePacked(bidId, uint256(9)));

        uint256 existing;
        assembly { existing := sload(add(base, 1)) }
        require(msg.value > existing, "BID: New bid too low");

        if (existing > 0) {
            uint256 oldBidder;
            assembly { oldBidder := sload(add(base, 2)) }
            _addPendingWithdrawal(address(uint160(oldBidder)), existing);
        }

        assembly { 
            sstore(base, or(x, shl(8, y)))
            sstore(add(base, 1), msg.value)
            sstore(add(base, 2), caller())
        }

        emit BlockplotsBidCreated(bidId, msg.value, msg.sender);
    }

    function pendingWithdrawals(address user) external view returns (uint256) {
        return _pendingWithdrawals(user);
    }

    function GlobalBidIDCounter() external view returns (uint256) {
        return _globalBidIDCounter;
    }

    // Internal functions
    function _grantRole(bytes32 role, address account) internal {
        if (!hasRole(role, account)) {
            bytes32 slot = keccak256(abi.encodePacked(role, account, uint256(0)));
            assembly { sstore(slot, 1) }

            bytes32 countSlot = keccak256(abi.encodePacked(role, uint256(1)));
            assembly { sstore(countSlot, add(sload(countSlot), 1)) }

            emit RoleGranted(role, account, msg.sender);
        }
    }

    function _revokeRole(bytes32 role, address account) internal {
        if (hasRole(role, account)) {
            bytes32 slot = keccak256(abi.encodePacked(role, account, uint256(0)));
            assembly { sstore(slot, 0) }

            bytes32 countSlot = keccak256(abi.encodePacked(role, uint256(1)));
            assembly { sstore(countSlot, sub(sload(countSlot), 1)) }

            emit RoleRevoked(role, account, msg.sender);
        }
    }

    function _getElevation(uint8 x, uint8 y) internal view returns (uint8) {
        (bool success, bytes memory data) = _elevationRetriever.staticcall(
            abi.encodeWithSelector(0x4166c1fd, x, y)
        );
        require(success);
        return abi.decode(data, (uint8));
    }

    function _getOwner(uint8 x, uint8 y) internal view returns (address) {
        (bool success, bytes memory data) = _blockplots.staticcall(
            abi.encodeWithSelector(0xe039e4a1, x, y)
        );
        require(success);
        return abi.decode(data, (address));
    }

    function _setOwner(uint8 x, uint8 y, address newOwner) internal {
        (bool success, ) = _blockplots.call(
            abi.encodeWithSelector(0x7d5fec5a, x, y, newOwner)
        );
        require(success);
    }

    function _computeId(uint8 x, uint8 y, uint8 elevation) internal pure returns (uint16) {
        return uint16((uint256(x) << 8) | y + (uint256(elevation) * 33));
    }

    function _getAsks(uint16 askId) internal view returns (uint128) {
        bytes32 slot = keccak256(abi.encodePacked(askId, uint256(12)));
        uint256 val;
        assembly { val := sload(slot) }
        return uint128(val);
    }

    function _pendingWithdrawals(address user) internal view returns (uint256) {
        bytes32 slot = keccak256(abi.encodePacked(user, uint256(11)));
        uint256 val;
        assembly { val := sload(slot) }
        return val;
    }

    function _addPendingWithdrawal(address user, uint256 amount) internal {
        bytes32 slot = keccak256(abi.encodePacked(user, uint256(11)));
        assembly { sstore(slot, add(sload(slot), amount)) }
    }

    receive() external payable {}
}
