// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

contract ERC1155Mintable {
    // Events
    event TransferSingle(address indexed operator, address indexed from, address indexed to, uint256 id, uint256 value);
    event TransferBatch(address indexed operator, address indexed from, address indexed to, uint256[] ids, uint256[] values);
    event ApprovalForAll(address indexed account, address indexed operator, bool approved);
    event OwnershipTransferred(address indexed previousOwner, address indexed newOwner);
    event OwnershipHandoverRequested(address indexed pendingOwner);
    event OwnershipHandoverCanceled(address indexed pendingOwner);
    event DefaultRoyaltySet(address indexed receiver, uint96 feeNumerator);
    event TokenRoyaltySet(uint256 indexed tokenId, address indexed receiver, uint96 feeNumerator);
    event SetCosigner(address indexed cosigner);
    event Withdraw(uint256 amount);
    event WithdrawERC20(address indexed token, uint256 amount);
    event Initialized(uint8 version);

    // Errors
    error Unauthorized();
    error NotAuthorized();
    error InvalidStage();
    error NoSupplyLeft();
    error RoyaltyOverflow();
    error RoyaltyReceiverIsZeroAddress();
    error NotTransferable();
    error TransferFromFailed();
    error TransferFailed();
    error InvalidProof();
    error AlreadyInitialized();
    error NoHandoverRequest();
    error NewOwnerIsZeroAddress();
    error Reentrancy();
    error WalletStageLimitExceeded();
    error GlobalWalletLimitOverflow();
    error InsufficientStageTimeGap();
    error TimestampExpired();
    error Panic(uint256 code);

    // Storage
    uint8 private _initialized;
    address private _owner;
    address private _pendingOwner;
    uint64 private _handoverExpiresAt;
    address private _cosigner;
    address private _royaltyReceiver;
    uint96 private _royaltyFeeNumerator;
    bool private _transferable;
    uint256 private _numberStages;
    uint256 private _timestampExpirySeconds;
    address private _mintCurrency;
    uint256 private _handoverTimeout;

    // Mappings
    mapping(address => mapping(address => bool)) private _operatorApprovals;
    mapping(address => mapping(uint256 => uint256)) private _balances;
    mapping(uint256 => uint256) private _totalSupply;
    mapping(uint256 => RoyaltyInfo) private _tokenRoyalties;
    mapping(address => bool) private _authorizedMinters;
    mapping(address => uint256) private _totalMintedByAddress;
    mapping(uint256 => StageInfo) private _stages;
    mapping(address => uint256) private _walletMintedPerStage;
    mapping(bytes32 => uint256) private _stageSupplies;

    struct RoyaltyInfo {
        address receiver;
        uint96 royaltyFraction;
    }

    struct StageInfo {
        uint64 startTime;
        uint64 endTime;
        uint96 walletLimit;
        uint96 stageSupply;
        uint256 price;
        uint32 merkleRootIndex;
    }

    uint256 private constant _HANDOVER_TIMEOUT = 1 days;
    uint256 private constant _MAX_ROYALTY = 10000;

    modifier onlyOwner() {
        if (msg.sender != _owner) revert Unauthorized();
        _;
    }

    modifier onlyAuthorizedMinter() {
        if (!_authorizedMinters[msg.sender] && msg.sender != _owner) revert NotAuthorized();
        _;
    }

    modifier nonReentrant() {
        uint256 status;
        assembly {
            status := sload(0xff)
        }
        if (status != 0) revert Reentrancy();
        assembly {
            sstore(0xff, 1)
        }
        _;
        assembly {
            sstore(0xff, 0)
        }
    }

    constructor() {
        _initialized = 1;
    }

    function initialize(string calldata name_, string calldata symbol_, address cosigner_) external {
        if (_initialized != 0) revert AlreadyInitialized();
        _initialized = 1;
        _owner = msg.sender;
        _cosigner = cosigner_;
        emit Initialized(1);
        emit OwnershipTransferred(address(0), msg.sender);
        emit SetCosigner(cosigner_);
    }

    function supportsInterface(bytes4 interfaceId) external pure returns (bool) {
        return interfaceId == 0x01ffc9a7 || // ERC165
               interfaceId == 0x2a55205a || // ERC2981
               interfaceId == 0xd9b67a26 || // ERC1155
               interfaceId == 0x0e89341c;   // ERC1155MetadataURI
    }

    function name() external pure returns (string memory) {
        return "";
    }

    function symbol() external pure returns (string memory) {
        return "";
    }

    function uri(uint256) external pure returns (string memory) {
        return "";
    }

    function setURI(string calldata) external onlyOwner {
        // Implementation specific
    }

    function balanceOf(address account, uint256 id) external view returns (uint256) {
        return _balances[account][id];
    }

    function balanceOfBatch(address[] calldata accounts, uint256[] calldata ids) external view returns (uint256[] memory) {
        require(accounts.length == ids.length, "length mismatch");
        uint256[] memory batchBalances = new uint256[](accounts.length);
        for (uint256 i = 0; i < accounts.length; i++) {
            batchBalances[i] = _balances[accounts[i]][ids[i]];
        }
        return batchBalances;
    }

    function setApprovalForAll(address operator, bool approved) external {
        _operatorApprovals[msg.sender][operator] = approved;
        emit ApprovalForAll(msg.sender, operator, approved);
    }

    function isApprovedForAll(address account, address operator) external view returns (bool) {
        return _operatorApprovals[account][operator];
    }

    function safeTransferFrom(address from, address to, uint256 id, uint256 amount, bytes calldata data) external {
        require(to != address(0), "transfer to zero");
        require(from == msg.sender || _operatorApprovals[from][msg.sender], "not approved");
        if (!_transferable) revert NotTransferable();

        _balances[from][id] -= amount;
        _balances[to][id] += amount;
        emit TransferSingle(msg.sender, from, to, id, amount);

        if (to.code.length > 0) {
            try IERC1155Receiver(to).onERC1155Received(msg.sender, from, id, amount, data) returns (bytes4 response) {
                require(response == IERC1155Receiver.onERC1155Received.selector, "invalid receiver");
            } catch {
                revert("transfer to non-ERC1155 receiver");
            }
        }
    }

    function safeBatchTransferFrom(address from, address to, uint256[] calldata ids, uint256[] calldata amounts, bytes calldata data) external {
        require(to != address(0), "transfer to zero");
        require(ids.length == amounts.length, "length mismatch");
        require(from == msg.sender || _operatorApprovals[from][msg.sender], "not approved");
        if (!_transferable) revert NotTransferable();

        for (uint256 i = 0; i < ids.length; i++) {
            _balances[from][ids[i]] -= amounts[i];
            _balances[to][ids[i]] += amounts[i];
        }
        emit TransferBatch(msg.sender, from, to, ids, amounts);

        if (to.code.length > 0) {
            try IERC1155Receiver(to).onERC1155BatchReceived(msg.sender, from, ids, amounts, data) returns (bytes4 response) {
                require(response == IERC1155Receiver.onERC1155BatchReceived.selector, "invalid receiver");
            } catch {
                revert("transfer to non-ERC1155 receiver");
            }
        }
    }

    function owner() external view returns (address) {
        return _owner;
    }

    function transferOwnership(address newOwner) external onlyOwner {
        if (newOwner == address(0)) revert NewOwnerIsZeroAddress();
        _pendingOwner = newOwner;
        _handoverExpiresAt = uint64(block.timestamp + _HANDOVER_TIMEOUT);
        emit OwnershipHandoverRequested(newOwner);
    }

    function completeOwnershipHandover(address newOwner) external {
        if (msg.sender != _pendingOwner) revert NoHandoverRequest();
        if (newOwner != _pendingOwner) revert NoHandoverRequest();
        if (block.timestamp > _handoverExpiresAt) revert TimestampExpired();

        address oldOwner = _owner;
        _owner = newOwner;
        _pendingOwner = address(0);
        emit OwnershipTransferred(oldOwner, newOwner);
    }

    function cancelOwnershipHandover() external onlyOwner {
        _pendingOwner = address(0);
        emit OwnershipHandoverCanceled(msg.sender);
    }

    function requestOwnershipHandover() external {
        if (msg.sender != _pendingOwner) revert NoHandoverRequest();
    }

