        _tokenRoyalties[tokenId] = RoyaltyInfo(receiver, feeNumerator);
        emit TokenRoyaltySet(tokenId, receiver, feeNumerator);
    }

    function royaltyInfo(uint256 tokenId, uint256 salePrice) external view returns (address, uint256) {
        RoyaltyInfo storage royalty = _tokenRoyalties[tokenId];
        if (royalty.receiver == address(0)) {
            return (_royaltyReceiver, (salePrice * _royaltyFeeNumerator) / _MAX_ROYALTY);
        }
        return (royalty.receiver, (salePrice * royalty.royaltyFraction) / _MAX_ROYALTY);
