    }

    function totalSupply(uint256 id) external view returns (uint256) {
        return _totalSupply[id];
    }

    function exists(uint256 id) external view returns (bool) {
        return _totalSupply[id] > 0;
    }

    function totalMintedByAddress(address account) external view returns (uint256) {
        return _totalMintedByAddress[account];
    }

    function getNumberStages() external view returns (uint256) {
        return _numberStages;
    }

    function getTimestampExpirySeconds() external view returns (uint256) {
        return _timestampExpirySeconds;
    }

    function getMintCurrency() external view returns (address) {
        return _mintCurrency;
    }

    function getStageInfo(uint256 stageIndex) external view returns (StageInfo memory) {
        return _stages[stageIndex];
    }

    function getActiveStageFromTimestamp(uint256 timestamp) external view returns (uint256) {
        for (uint256 i = 0; i < _numberStages; i++) {
            if (timestamp >= _stages[i].startTime && timestamp < _stages[i].endTime) {
                return i;
            }
        }
        revert InvalidStage();
    }

    function withdraw() external onlyOwner {
        uint256 balance = address(this).balance;
        (bool success, ) = payable(msg.sender).call{value: balance}("");
        if (!success) revert TransferFailed();
        emit Withdraw(balance);
    }

    function withdrawERC20() external onlyOwner {
        // Implementation for ERC20 withdrawal
    }

    function mint(address to, uint256 id, uint256 amount, bytes calldata data) external onlyAuthorizedMinter {
        require(to != address(0), "mint to zero");
        _balances[to][id] += amount;
        _totalSupply[id] += amount;
        emit TransferSingle(msg.sender, address(0), to, id, amount);

        if (to.code.length > 0) {
            try IERC1155Receiver(to).onERC1155Received(msg.sender, address(0), id, amount, data) returns (bytes4 response) {
                require(response == IERC1155Receiver.onERC1155Received.selector, "invalid receiver");
            } catch {
                revert("mint to non-ERC1155 receiver");
            }
        }
    }

    function mintBatch(address to, uint256[] calldata ids, uint256[] calldata amounts, bytes calldata data) external onlyAuthorizedMinter {
        require(to != address(0), "mint to zero");
        require(ids.length == amounts.length, "length mismatch");

        for (uint256 i = 0; i < ids.length; i++) {
            _balances[to][ids[i]] += amounts[i];
            _totalSupply[ids[i]] += amounts[i];
        }
        emit TransferBatch(msg.sender, address(0), to, ids, amounts);

        if (to.code.length > 0) {
            try IERC1155Receiver(to).onERC1155BatchReceived(msg.sender, address(0), ids, amounts, data) returns (bytes4 response) {
                require(response == IERC1155Receiver.onERC1155BatchReceived.selector, "invalid receiver");
            } catch {
                revert("mint to non-ERC1155 receiver");
            }
        }
    }

    function onERC1155Received(address, address, uint256, uint256, bytes calldata) external pure returns (bytes4) {
        return IERC1155Receiver.onERC1155Received.selector;
    }

    function onERC1155BatchReceived(address, address, uint256[] calldata, uint256[] calldata, bytes calldata) external pure returns (bytes4) {
        return IERC1155Receiver.onERC1155BatchReceived.selector;
    }

    receive() external payable {}
}

interface IERC1155Receiver {
    function onERC1155Received(address operator, address from, uint256 id, uint256 value, bytes calldata data) external returns (bytes4);
    function onERC1155BatchReceived(address operator, address from, uint256[] calldata ids, uint256[] calldata values, bytes calldata data) external returns (bytes4);
}
